{
  "name": "FirebaseAnalytics",
  "version": "12.19.0",
  "summary": "Firebase Analytics for iOS",
  "description": "Firebase Analytics is a free, out-of-the-box analytics solution that\ninspires actionable insights based on app usage and user engagement.",
  "homepage": "https://firebase.google.com/features/analytics/",
  "license": {
    "type": "Apache-2.0",
    "file": "LICENSE"
  },
  "authors": "Google, Inc.",
  "source": {
    "http": "https://dl.google.com/firebase/ios/analytics/f02e7923f9b32c38/FirebaseAnalytics-12.19.0.tar.gz"
  },
  "cocoapods_version": ">= 1.12.0",
  "swift_versions": "5.9",
  "platforms": {
    "ios": "15.0",
    "osx": "10.15",
    "tvos": "15.0"
  },
  "libraries": [
    "c++",
    "sqlite3",
    "z"
  ],
  "frameworks": "StoreKit",
  "dependencies": {
    "FirebaseCore": [
      "~> 12.19.0"
    ],
    "FirebaseInstallations": [
      "~> 12.19.0"
    ],
    "GoogleUtilities/AppDelegateSwizzler": [
      "~> 8.1"
    ],
    "GoogleUtilities/MethodSwizzler": [
      "~> 8.1"
    ],
    "GoogleUtilities/NSData+zlib": [
      "~> 8.1"
    ],
    "GoogleUtilities/Network": [
      "~> 8.1"
    ],
    "nanopb": [
      "~> 3.30910.0"
    ]
  },
  "default_subspecs": "Default",
  "subspecs": [
    {
      "name": "Default",
      "dependencies": {
        "GoogleAppMeasurement/Default": [
          "12.19.0"
        ]
      },
      "vendored_frameworks": "Frameworks/FirebaseAnalytics.xcframework"
    },
    {
      "name": "Core",
      "dependencies": {
        "GoogleAppMeasurement/Core": [
          "12.19.0"
        ]
      },
      "vendored_frameworks": "Frameworks/FirebaseAnalytics.xcframework"
    },
    {
      "name": "IdentitySupport",
      "dependencies": {
        "GoogleAppMeasurement/IdentitySupport": [
          "12.19.0"
        ]
      },
      "vendored_frameworks": "Frameworks/FirebaseAnalytics.xcframework"
    }
  ],
  "swift_version": "5.9"
}
